style:
.tw-cosolar--bijian.resume-paper {
  color: #273b40;
}

.tw-cosolar--bijian.resume-paper .paper-header {
  position: relative;
  display: block;
  margin: 0 0 7mm;
  padding: 0 0 4.5mm;
  border: none;
  border-top: 2.2mm solid #2f7f8f;
  border-bottom: 1px solid #dcebed;
  print-color-adjust: exact;
}

.tw-cosolar--bijian.resume-paper .paper-header::before {
  content: "个人简历";
  display: block;
  margin: 3.6mm 0 2.4mm;
  color: #22616d;
  font-size: calc(var(--paper-base-size) * 1.72);
  font-weight: 700;
  letter-spacing: 0.24em;
  line-height: 1.15;
}

.tw-cosolar--bijian.resume-paper .paper-header__main {
  padding-right: 36mm;
}

.tw-cosolar--bijian.resume-paper .paper-photo {
  position: absolute;
  top: 7mm;
  right: 0;
  width: 29mm;
  height: 37mm;
  border: 0.5mm solid #d3e3e6;
  border-radius: 1mm;
  box-shadow: none;
  print-color-adjust: exact;
}

.tw-cosolar--bijian.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef6f7;
  color: #2f7f8f;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 600;
}

.tw-cosolar--bijian.resume-paper .paper-name {
  color: #1b3c43;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.02);
  letter-spacing: 0.06em;
}

.tw-cosolar--bijian.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #5f7d83;
}

.tw-cosolar--bijian.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #2f7f8f;
  font-weight: 600;
}

.tw-cosolar--bijian.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #7d979c;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-cosolar--bijian.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.2mm 8mm;
  margin-top: 3mm;
  padding-top: 2.8mm;
  border-top: 1px solid #e2edef;
  color: #334d53;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--bijian.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--bijian.resume-paper .paper-contact__label {
  color: #7d979c;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  padding: 1.5mm 3mm;
  background: #2f7f8f;
  border-radius: 0.6mm;
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1);
  letter-spacing: 0.14em;
  print-color-adjust: exact;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-section__icon {
  display: grid;
  place-items: center;
  width: 4.6mm;
  height: 4.6mm;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  color: #fff;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-section__icon svg {
  width: 58%;
  height: 58%;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-section__title::after {
  content: none;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-section__body {
  margin-top: 2.4mm;
  color: #2f4248;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-item-title {
  color: #1c343a;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-item-period {
  color: #58757a;
  font-weight: 600;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-item-sub {
  color: #4a6268;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-note__tag {
  color: #2f7f8f;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-skill {
  flex-wrap: wrap;
  padding-bottom: 1.6mm;
  border-bottom: none;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-skill__dots {
  display: inline-flex;
  gap: 0.9mm;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-skill__dots i {
  width: 6.5mm;
  height: 1.3mm;
  border-radius: 0.6mm;
  background: #e1ecee;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-skill__dots i.filled {
  background: #2f7f8f;
}

.tw-cosolar--bijian.resume-paper .paper-section .paper-skill__level {
  display: none;
}

.tw-cosolar--bijian.resume-paper .paper-section.is-job_intention .paper-item-head {
  display: flex;
  gap: 4mm;
  padding: 2mm 3mm;
  border-left: 1mm solid #2f7f8f;
  background: #f4f9fa;
  print-color-adjust: exact;
}

.tw-cosolar--bijian.resume-paper .paper-section.is-job_intention .paper-item-period {
  margin-left: auto;
  color: #2f7f8f;
}

.tw-cosolar--bijian.resume-paper .paper-section.is-job_intention .paper-item-sub {
  margin-top: 1mm;
  padding-left: 4mm;
  color: #58757a;
}

.tw-cosolar--bijian.resume-paper .paper-footer {
  border-top: 1px solid #dcebed;
  color: #708a90;
}
